INSERT INTO `ai_suggestion_history` (`id`, `school_id`, `school_year`, `dimension_id`, `suggestion_title`, `suggestion_text`, `last_cycle_note`, `priority_label`, `decline_risk`, `data_status`, `score_at_time`, `model_version`, `is_final`, `needs_review`, `adopted_plan_id`, `generated_by`, `generated_at`, `is_sample`) VALUES
(1, 1, 'CBRANKDEMO-01', 4, 'Advance governance and accountability systems', '**Reinforce governance and accountability**. Operationalize the strategic plan and strengthen monitoring (indicators 4.1, 4.5, 4.6).\n- Governance committee translates the strategic plan into an operational implementation plan; submit to school head within three weeks.\n- Monitoring officer establishes a quarterly program evaluation schedule; first evaluation in 30 days.\n- Stakeholder liaison conducts bi‑annual satisfaction surveys with parents and partners; report findings to board by end of each semester.', NULL, 'Medium', 'medium', 'sufficient', 45.80, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:01:00', 0),
(2, 1, 'CBRANKDEMO-01', 2, 'Enhance inclusive learning environment', '**Improve learning environment**. Address gaps in ALS, special‑education, and access for disadvantaged learners (indicators 2.5, 2.6, 2.10).\n- Facilities officer upgrades ALS classroom resources; complete by end of term.\n- Guidance counselor ensures special‑education and PWD‑friendly facilities meet standards; conduct quarterly checks.\n- Community liaison partners with NGOs to provide learning kits for disadvantaged learners; deliver kits within 45 days.', NULL, 'Medium', 'medium', 'sufficient', 47.50, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:01:00', 0),
(3, 1, 'CBRANKDEMO-01', 6, 'Upgrade essential facilities and technology', '**Improve facilities and resource management**. Ensure functional infrastructure and ICT resources (indicators 6.4, 6.5).\n- Facilities manager repairs water, electricity, and internet infrastructure; complete critical fixes within 60 days.\n- ICT coordinator sets up a functional computer laboratory with regular maintenance schedule; initial setup by end of month.\n- Finance officer allocates a budget line for ongoing facility upkeep; review allocation each fiscal quarter.', NULL, 'Low', 'medium', 'sufficient', 64.30, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:01:00', 0),
(4, 1, 'CBRANKDEMO-01', 3, 'Strengthen school leadership practices', '**Elevate leadership effectiveness**. Build cohesive leadership routines to support school goals.\n- School head leads a monthly leadership forum with department heads to align actions with the school vision; first session within two weeks.\n- Assistant principal develops a 6‑month action plan linking strategic goals to classroom practices; draft due in one month.\n- All leaders complete DepEd Order No. 007, s. 2024 compliance training; finish by end of quarter.', NULL, 'Medium', 'medium', 'sufficient', 50.00, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:01:00', 0),
(5, 1, 'CBRANKDEMO-01', 5, 'Develop human resources and team capacity', '**Build staff capacity and motivation**. Strengthen performance, professional development, and recognition (indicators 5.1, 5.3, 5.4, 5.5, 5.7).\n- HR officer launches a needs‑based Learning Action Cell schedule; meet monthly, starting next month.\n- Professional development coordinator organizes CPD workshops aligned with DepEd Order No. 007, s. 2024; hold at least two sessions per semester.\n- School head implements a transparent teacher workload allocation matrix; review and adjust quarterly.\n- Recognition committee creates a milestone awards program; present awards at each term‑end ceremony.', NULL, 'Medium', 'medium', 'sufficient', 53.60, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:01:00', 0),
(6, 1, 'CBRANKDEMO-01', 1, 'Boost early literacy and numeracy outcomes', '**Strengthen curriculum delivery**. Focus on Grade 3 proficiency as highlighted in indicator 1.1. Implement targeted interventions.\n- Classroom teachers conduct weekly diagnostic assessments for Grade 3 learners; lead teacher to coordinate, report by end of each week.\n- Curriculum coordinator designs remedial lesson plans aligned with DepEd Order No. 007, s. 2024; to be ready within two weeks.\n- School head monitors progress through monthly data‑review meetings; schedule first meeting within 30 days.', NULL, 'Low', 'medium', 'sufficient', 65.60, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:01:00', 0),
(7, 1, 'CBRANKDEMO-01', 5, 'Elevate Teacher Performance and Development', '**Human Resource and Team Development** Targeting personnel growth addresses the 53.6% score. Indicators 5.1, 5.4, 5.5, 5.7 can be addressed:\n- Department Chairs will set individual performance targets for teachers and review them during the semi‑annual performance commitment meetings (Indicator 5.1).\n- Professional Development Coordinator will organize monthly CPD workshops aligned with identified needs (Indicator 5.4).\n- HR Officer will design a recognition program that awards milestone achievements each semester (Indicator 5.5).\n- School Head will monitor teacher workload distribution and adjust assignments quarterly to ensure equity (Indicator 5.7).', NULL, 'Medium', 'medium', 'sufficient', 53.60, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:07:33', 0),
(8, 1, 'CBRANKDEMO-01', 4, 'Enhance Governance and Accountability Systems', '**Governance and Accountability** Improving oversight can lift the 45.8% score. Use indicators 4.1, 4.5, 4.6:\n- School Head will translate the strategic plan into an operational implementation plan, finalizing it by 30 September 2026 (Indicator 4.1).\n- Internal Audit Team will establish a quarterly monitoring and evaluation schedule, producing reports every three months (Indicator 4.5).\n- Stakeholder Relations Officer will conduct bi‑annual satisfaction surveys with parents and community partners, reporting results to the school council (Indicator 4.6).', NULL, 'Medium', 'medium', 'sufficient', 45.80, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:07:33', 0),
(9, 1, 'CBRANKDEMO-01', 2, 'Strengthen Inclusive Learning Spaces', '**Learning Environment** To raise the 47.5% score, focus on accessibility and ALS support. Relevant indicators 2.5, 2.6, 2.10 guide the actions:\n- Facilities Officer will audit classrooms for special‑education and PWD accommodations and submit a remediation plan by 31 October 2026 (Indicator 2.10).\n- ALS Coordinator will schedule weekly ALS sessions and ensure required materials are available, reporting attendance monthly (Indicator 2.6).\n- Guidance Counselor will develop outreach activities for disadvantaged and out‑of‑school youth, launching the program by 15 December 2026 (Indicator 2.5).', NULL, 'Medium', 'medium', 'sufficient', 47.50, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:07:33', 0),
(10, 1, 'CBRANKDEMO-01', 6, 'Upgrade Essential Infrastructure and ICT', '**Finance and Resource Management and Mobilization** Enhancing facilities supports learning. Indicators 6.4 and 6.5:\n- Finance Officer will prepare a budget proposal for water, electricity, and internet upgrades and submit it to the Division by 15 October 2026 (Indicator 6.4).\n- ICT Coordinator will inventory existing computer lab assets and develop a refurbishment plan, completing upgrades by 31 January 2027 (Indicator 6.5).\n- Facilities Officer will schedule monthly maintenance checks for utilities and lab equipment, documenting compliance in a logbook (Indicator 6.4).', NULL, 'Low', 'medium', 'sufficient', 64.30, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:07:33', 0),
(11, 1, 'CBRANKDEMO-01', 3, 'Advance Strategic Leadership Planning', '**Leadership** Strengthening leadership will help sustain progress. Indicator 3.1 suggests:\n- School Head will lead a strategic‑plan drafting workshop with department heads, completing the draft by 20 November 2026 (Indicator 3.1).\n- Vice‑Principal will assign responsibilities and set quarterly milestones, updating the board each quarter (Indicator 3.1).\n- Monitoring Committee will conduct a mid‑year review of plan implementation and present findings to the Division on 15 March 2027 (Indicator 3.1).', NULL, 'Medium', 'medium', 'sufficient', 50.00, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:07:33', 0),
(12, 1, 'CBRANKDEMO-01', 1, 'Boost Grade 3 Literacy and Numeracy', '**Curriculum and Teaching** The current score indicates solid performance but early grade outcomes need attention. For indicator 1.1, consider these steps:\n- Principal together with Grade 3 teachers will administer baseline literacy and numeracy assessments by 15 September 2026 (Indicator 1.1).\n- Teachers will design targeted intervention lessons and implement them twice weekly, monitoring progress each month (Indicator 1.1).\n- School Learning Action Cell will review intervention data and report improvements to the Division Office by 30 November 2026 (Indicator 1.1).', NULL, 'Low', 'medium', 'sufficient', 65.60, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 11:07:33', 0),
(13, 1, 'CBRANKDEMO-01', 4, 'Enhance Governance and Accountability Mechanisms', '**Governance and Accountability**\nRobust monitoring and stakeholder feedback improve trust and outcomes.\n- Governance Committee: Conduct bi‑monthly stakeholder satisfaction surveys and compile results for the School Head (indicator 4.6).\n- Internal Audit Team: Implement a quarterly program and project evaluation checklist, reporting findings by the 10th of the following month (indicator 4.5).\n- School Head: Ensure the strategic implementation plan is operationalized, reviewing its status in every monthly leadership meeting (indicator 4.1).', NULL, 'Medium', 'medium', 'sufficient', 45.80, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 11:11:41', 0),
(14, 1, 'CBRANKDEMO-01', 2, 'Upgrade Learning Environment Infrastructure', '**Learning Environment**\nA functional, well‑equipped environment supports effective instruction. Prioritize essential facilities.\n- ICT Coordinator: Ensure the computer laboratory is fully operational and schedule weekly maintenance, completing by end of Q1 (indicator 6.5).\n- Facilities Officer: Verify water, electricity, and internet services are reliable; conduct monthly checks and report by the 5th of each month (indicator 6.4).\n- ALS Coordinator: Activate the school‑based ALS program and provide weekly sessions for out‑of‑school youth, launching by the start of Q2 (indicator 2.6).', NULL, 'Medium', 'medium', 'sufficient', 47.50, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 11:11:41', 0),
(15, 1, 'CBRANKDEMO-01', 6, 'Improve Resource Management and Mobilization', '**Finance and Resource Management and Mobilization**\nEffective resource allocation underpins all school activities.\n- Finance Officer: Prepare a quarterly budget utilization report linking expenditures to learning outcomes, due by the 20th of the month following each quarter.\n- Facilities Officer: Prioritize maintenance of the computer lab and utilities, completing a checklist of required repairs by the end of each month (indicators 6.5, 6.4).\n- School Head: Seek additional funding partners and submit at least one grant proposal per semester, with drafts ready by mid‑Q2.', NULL, 'Low', 'medium', 'sufficient', 64.30, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 11:11:41', 0),
(16, 1, 'CBRANKDEMO-01', 1, 'Enhance Early Literacy Outcomes', '**Curriculum and Teaching**\nImproving foundational skills will raise overall performance. Focus on Grade 3 proficiency.\n- Curriculum Coordinator: Conduct diagnostic assessment for Grade 3 learners by end of Q1 (indicator 1.1).\n- Grade 3 Teachers: Implement targeted remedial lessons twice a week for identified learners throughout Q2.\n- School Head: Review assessment data and approve additional learning materials by mid‑Q2.', NULL, 'Low', 'medium', 'sufficient', 65.60, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 11:11:41', 0),
(17, 1, 'CBRANKDEMO-01', 3, 'Strengthen Strategic Leadership Processes', '**Leadership**\nClear strategic direction and monitoring are essential for school improvement.\n- School Head: Draft a comprehensive strategic plan aligned with DepEd Order No. 007, s. 2024 by the end of Q2 (indicator 3.1).\n- Planning Committee: Translate the strategic plan into an actionable implementation plan with quarterly milestones by early Q3 (indicator 4.1).\n- Monitoring Team: Establish a monthly review schedule to evaluate progress against the plan and adjust actions as needed, starting Q3.', NULL, 'Medium', 'medium', 'sufficient', 50.00, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 11:11:41', 0),
(18, 1, 'CBRANKDEMO-01', 5, 'Boost Teacher Development and Workload Management', '**Human Resource and Team Development**\nInvesting in staff growth and equitable workload drives school performance.\n- HR Officer: Organize quarterly Learning Action Cells focused on identified needs, beginning Q2 (indicator 5.3).\n- Department Heads: Review teacher workload distribution each semester and adjust assignments to ensure fairness (indicator 5.7).\n- School Head: Launch a semi‑annual recognition program for milestone achievements, with nominations due by the 15th of the preceding month (indicator 5.5).', NULL, 'Medium', 'medium', 'sufficient', 53.60, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 11:11:41', 0),
(19, 1, '2001-2002', 25, 'Enhance curriculum relevance and delivery', '**Strengthen curriculum delivery** The current score suggests room for growth in aligning lessons with DepEd values. Consider targeted actions:\n- Teachers (lead: Head of Curriculum) will conduct bi‑monthly workshops on integrating peace and core values (indicator 1.6) starting June 2024.\n- Grade 3 teachers will adopt weekly lesson‑plan reviews to ensure contextualized materials meet learner needs (indicator 1.4) by end of August 2024.\n- ALS coordinators will organize quarterly certification prep sessions for learners to achieve elementary/junior high completion (indicator 1.3) beginning Q3 2024.', NULL, 'Low', 'medium', 'sufficient', 67.80, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:09:45', 0),
(20, 1, '2001-2002', 26, 'Promote a safe and inclusive learning environment', '**Create a nurturing school climate** A low score indicates need to strengthen anti‑bullying and child‑protection measures. Actions include:\n- Guidance Counselors (with Principal) will launch a monthly anti‑bullying awareness campaign (indicator 2.1) starting July 2024.\n- Child‑Protection Committee members will conduct bimonthly training on safeguarding protocols (indicator 2.7) with first session by September 2024.\n- Facilities Officer will ensure special‑education‑friendly spaces are audited and upgraded quarterly (indicator 2.10) with initial audit by October 2024.', NULL, 'Low', 'medium', 'sufficient', 66.00, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:09:45', 0),
(21, 1, '2001-2002', 27, 'Strengthen school leadership and community planning', '**Boost leadership collaboration** The leadership dimension can improve by activating community planning mechanisms. Steps:\n- School Head will convene a School‑Community Planning Team meeting each term to set joint goals (indicator 3.2) beginning Term 2 2024.\n- Vice Principal will develop a leadership reflection journal, reviewed monthly, to monitor decision‑making effectiveness.\n- All department heads will submit quarterly progress reports on community‑linked initiatives to the Principal.', NULL, 'Low', 'medium', 'sufficient', 66.90, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:09:45', 0),
(22, 1, '2001-2002', 28, 'Enhance governance and stakeholder accountability', '**Advance governance practices** Strengthening plan implementation and stakeholder feedback will support higher scores. Actions:\n- Governance Committee (Chair: School Head) will finalize an implementation roadmap for the strategic plan by 30 June 2024 (indicator 4.1).\n- Internal Audit Officer will conduct semi‑annual stakeholder satisfaction surveys and report findings (indicator 4.6) starting August 2024.\n- All department heads will present quarterly compliance checklists to the Governance Committee to ensure alignment with policies.', NULL, 'Low', 'medium', 'sufficient', 70.80, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:09:45', 0),
(23, 1, '2001-2002', 29, 'Improve human resource processes and compensation timeliness', '**Streamline HR operations** Timely salary and allowance delivery is essential for staff morale. Steps:\n- HR Officer will verify payroll data weekly and resolve discrepancies within 3 business days (indicator 5.6) starting May 2024.\n- Finance Assistant will generate monthly salary disbursement reports for audit by the Principal.\n- School Head will hold bi‑monthly staff briefings to communicate compensation updates and address concerns.', NULL, 'Low', 'medium', 'sufficient', 67.10, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:09:45', 0),
(24, 1, '2001-2002', 30, 'Optimize financial resource utilization and facility oversight', '**Strengthen financial management** Better use of MOOE and regular facility checks will raise the finance score. Actions:\n- Finance Officer will monitor MOOE utilization monthly and aim for 85% compliance (indicator 6.6) with report due the 5th of each month.\n- Facilities Supervisor will perform a quarterly inspection of infrastructure and facilities (indicator 6.1) with checklist submitted by 15th of the month following inspection.\n- School Head will approve an annual budget reallocation plan by 31 March 2025 to address identified gaps.', NULL, 'Low', 'medium', 'sufficient', 72.50, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:09:45', 0),
(25, 1, '2001-2002', 25, 'Strengthen Curriculum Alignment', '**Curriculum and Teaching**\nThe current score indicates moderate performance; focusing on lesson relevance can boost outcomes.\n- Teachers (lead) will integrate peace and DepEd core values into weekly lesson plans (indicator 1.6), reviewed monthly.\n- Curriculum Coordinators will develop contextualized learning materials for all grade levels (indicator 1.4), completed by 30 June.\n- ALS Coordinator will ensure ALS learners attain certification by establishing quarterly assessment checkpoints (indicator 1.3), reporting each quarter.', NULL, 'Low', 'medium', 'sufficient', 67.80, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:12:06', 0),
(26, 1, '2001-2002', 26, 'Improve Learning Environment Safety', '**Learning Environment**\nA 66% score suggests the need to address bullying and inclusive facilities.\n- Guidance Counselors will launch a zero‑bullying awareness program (indicator 2.1) with monthly monitoring.\n- Facilities Officer will upgrade special‑education and PWD‑friendly facilities (indicator 2.10) with a completion deadline of 31 Dec.\n- Student Welfare Committee will organize culture‑sensitive activities each term (indicator 2.4).', NULL, 'Low', 'medium', 'sufficient', 66.00, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:12:06', 0),
(27, 1, '2001-2002', 27, 'Boost School Leadership Collaboration', '**Leadership**\nThe leadership score near 67% indicates an opportunity to strengthen community planning.\n- School Head will convene the school‑community planning team (indicator 3.2) monthly to set action items.\n- Vice Principal will mentor department heads on strategic plan execution, providing bi‑monthly progress reports.\n- Teachers will submit leadership reflections quarterly to inform decision‑making.', NULL, 'Low', 'medium', 'sufficient', 66.90, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:12:06', 0),
(28, 1, '2001-2002', 28, 'Enhance Governance Transparency', '**Governance and Accountability**\nScore above 70% is solid but can be raised by formalizing plans.\n- Governance Committee will operationalize the strategic plan through an implementation plan (indicator 4.1) by end of Q3.\n- Stakeholder Relations Officer will maintain stakeholder satisfaction ratings (indicator 4.6) via annual surveys and follow‑up actions.\n- School Head will publish quarterly governance reports on the school portal.', NULL, 'Low', 'medium', 'sufficient', 70.80, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:12:06', 0),
(29, 1, '2001-2002', 29, 'Strengthen HR Timeliness', '**Human Resource and Team Development**\nScore indicates a need to improve compensation processes.\n- HR Officer will ensure correct salaries, allowances, and additional compensation are processed within 5 business days of submission (indicator 5.6), with monthly audit.\n- Professional Development Coordinator will schedule quarterly training for teachers on DepEd Order No. 007, s. 2024.\n- School Head will conduct semi‑annual performance reviews and share feedback with staff.', NULL, 'Low', 'medium', 'sufficient', 67.10, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:12:06', 0),
(30, 1, '2001-2002', 30, 'Optimize Resource Utilization', '**Finance and Resource Management and Mobilization**\nScore above 70% but maintenance utilization can be improved.\n- Finance Officer will monitor MOOE utilization (indicator 6.6) monthly and report variances.\n- Facilities Manager will conduct bi‑monthly infrastructure inspections (indicator 6.1) and log findings.\n- School Head will develop an annual resource mobilization plan by 31 March, reviewed each semester.', NULL, 'Low', 'medium', 'sufficient', 72.50, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 12:12:06', 0),
(31, 1, '2001-2002', 25, 'Strengthen Curriculum Delivery and Materials', 'To boost learner outcomes, focus on contextualized resources and peace values.\n- Curriculum Coordinator to lead quarterly workshops for teachers on integrating peace and DepEd core values (indicator 1.6), with reports due first week of each month.\n- Grade Level Leaders to develop and share contextualized learning modules aligned with local community needs (indicator 1.4) by end of each term.\n- ALS Coordinator to monitor ALS learner certification progress and provide remedial support, updating records monthly (indicator 1.3).\n- Class Teachers to implement early literacy assessments for Grade 3 and plan interventions for learners below proficiency (indicator 1.1) within two weeks of assessment.', NULL, 'Low', 'medium', 'sufficient', 67.80, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 12:55:05', 0),
(32, 1, '2001-2002', 26, 'Promote a Safe and Inclusive School Climate', 'Creating a nurturing environment supports attendance and well‑being.\n- Guidance Counselor to oversee the Child‑Protection Committee, meeting monthly to review cases and ensure compliance (indicator 2.7).\n- Facilities Officer to audit playground and classroom safety quarterly, targeting zero bullying incidents (indicator 2.1) and report findings to the principal.\n- Teacher‑In‑Charge of extracurricular activities to organize culture‑sensitive events each semester (indicator 2.4) with student participation logs.\n- Special Education Coordinator to ensure PWD‑friendly facilities are maintained and accessible, conducting bi‑annual checks (indicator 2.10).', NULL, 'Low', 'medium', 'sufficient', 66.00, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 12:55:05', 0),
(33, 1, '2001-2002', 27, 'Enhance School‑Community Planning Leadership', 'Effective leadership links school plans with community partners.\n- School Head to convene the School‑Community Planning Team monthly, reviewing progress against the strategic plan (indicator 3.2).\n- Assistant Principal to draft an implementation timeline for the strategic plan and share it with all department heads within 30 days.\n- Community Liaison Officer to organize quarterly stakeholder forums to gather feedback and adjust plans accordingly.\n- Leadership Team to document decisions and monitor action items, submitting a summary report to the Division Office each term.', NULL, 'Low', 'medium', 'sufficient', 66.90, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 12:55:05', 0),
(34, 1, '2001-2002', 28, 'Strengthen Stakeholder Satisfaction and Plan Execution', 'Transparent governance builds trust and accountability.\n- Governance Committee Chair to conduct an annual satisfaction survey of internal and external stakeholders and present findings to the School Board (indicator 4.6).\n- Strategic Planning Officer to translate the school’s strategic plan into a detailed implementation plan, completing it within 60 days (indicator 4.1).\n- Principal to review implementation milestones quarterly and adjust resource allocation as needed.\n- School Secretary to maintain a public dashboard of key performance indicators, updating it monthly.', NULL, 'Low', 'medium', 'sufficient', 70.80, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 12:55:05', 0),
(35, 1, '2001-2002', 29, 'Ensure Timely Compensation and Staff Support', 'Prompt salary delivery motivates teachers and staff.\n- HR Officer to verify payroll data and process salaries, allowances, and other compensation by the 5th of each month (indicator 5.6).\n- Department Heads to conduct bi‑monthly staff development meetings focusing on professional growth and address concerns.\n- Principal to recognize exemplary staff performance in monthly assemblies, linking to DepEd Order No. 007, s. 2024.\n- HR Officer to maintain a tracking sheet of compensation disbursements and report any delays within one week.', NULL, 'Low', 'medium', 'sufficient', 67.10, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 12:55:05', 0),
(36, 1, '2001-2002', 30, 'Optimize Facility Maintenance and MOOE Utilization', 'Effective resource management sustains school operations.\n- Finance Officer to conduct a monthly review of Maintenance and Other Operating Expenses (MOOE) utilization, aiming for 75–100% compliance (indicator 6.6) and submit a report to the principal.\n- Facilities Manager to perform quarterly inspections of infrastructure and facilities, documenting findings (indicator 6.1) and prioritizing repairs.\n- Principal to approve a corrective action plan for identified maintenance needs within two weeks of each inspection.\n- Finance Officer to prepare an annual resource mobilization plan, presenting it to the school council by 30 June.', NULL, 'Low', 'medium', 'sufficient', 72.50, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 12:55:05', 0),
(37, 1, '2002-2003', 25, 'Deepen curriculum relevance and assessment', '**Curriculum and Teaching**\nBuilding on the recent score gain, focus on systematic curriculum mapping and data‑driven instruction.\n- Curriculum Coordinator conducts a semester‑end curriculum audit (indicator 1.6) and shares findings with department heads by the 10th of the following month.\n- Grade Level Leaders co‑create differentiated lesson‑plan templates (indicator 1.4) and pilot them in two classes each term.\n- Class Teachers implement monthly formative quizzes for core subjects (indicator 1.1) and compile a progress dashboard for the principal.', 'Last cycle: “Strengthen Curriculum Delivery and Materials”; Result: score improved by 13.8 from 67.8% to 81.6%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 81.60, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 14:01:19', 0),
(38, 1, '2002-2003', 26, 'Promote holistic and safe learning environment', '**Learning Environment**\nWith modest gains, reinforce protective measures and inclusive activities.\n- Guidance Counselor leads a quarterly child‑protection audit (indicator 2.2) and reports zero‑incident status to the principal.\n- Facilities Officer updates the school‑based ALS program schedule (indicator 2.6) and monitors attendance monthly.\n- Facilities Officer conducts quarterly safety inspections of playgrounds and classrooms (indicator 2.1) and logs findings for corrective action.\n- Teacher‑In‑Charge of extracurriculars organizes a bi‑annual cultural‑sensitivity workshop (indicator 2.4) for students and staff.', 'Last cycle: “Promote a Safe and Inclusive School Climate”; Result: score improved by 6.3 from 66.0% to 72.3%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 72.30, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 14:01:19', 0),
(39, 1, '2002-2003', 27, 'Strengthen community‑driven leadership processes', '**Leadership**\nTo sustain high performance, embed community feedback loops into planning.\n- School‑Community Planning Team meets monthly (indicator 3.2) to review action items and adjust timelines.\n- Assistant Principal prepares a quarterly leadership reflection report summarizing successes and challenges for the Division Office.\n- Community Liaison Officer hosts a semi‑annual stakeholder forum to gather input on school initiatives and documents outcomes.', 'Last cycle: “Enhance School‑Community Planning Leadership”; Result: score improved by 14.4 from 66.9% to 81.3%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 81.30, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 14:01:19', 0),
(40, 1, '2002-2003', 28, 'Enhance governance monitoring and council effectiveness', '**Governance and Accountability**\nGiven the static score, focus on systematic monitoring and council activation.\n- Governance Committee Chair convenes the School Governance Council quarterly (indicator 4.2) and records minutes on the public dashboard.\n- Strategic Planning Officer implements a bi‑annual program evaluation cycle (indicator 4.5) and shares results with the school board.\n- Principal publishes a monthly KPI summary (indicator 4.6) on the school website for stakeholder transparency.', 'Last cycle: “Strengthen Stakeholder Satisfaction and Plan Execution”; Result: score was unchanged from 70.8% to 70.8%, and no improvement plan was created.', 'Low', 'low', 'sufficient', 70.80, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 14:01:19', 0),
(41, 1, '2002-2003', 29, 'Optimize staff compensation and professional growth', '**Human Resource and Team Development**\nBuilding on improved remuneration timeliness, add professional development tracking.\n- HR Officer audits salary and allowance disbursements by the 5th of each month (indicator 5.6) and flags any delays within one week.\n- Department Heads organize quarterly professional‑development workshops aligned with DepEd Order No. 007, s. 2024.\n- Principal recognizes outstanding staff quarterly during assemblies, linking awards to performance metrics.', 'Last cycle: “Ensure Timely Compensation and Staff Support”; Result: score improved by 7.9 from 67.1% to 75.0%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 75.00, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 14:01:19', 0),
(42, 1, '2002-2003', 30, 'Advance infrastructure upgrades and financial compliance', '**Finance and Resource Management and Mobilization**\nTo protect recent gains, prioritize facility upgrades and budget adherence.\n- Finance Officer reviews MOOE utilization monthly (indicator 6.6) and submits compliance report to the principal.\n- Facilities Manager leads a bi‑annual infrastructure improvement plan (indicator 6.2) and schedules repairs within two weeks of identification.\n- Finance Officer drafts an annual resource‑mobilization strategy by 30 June and presents it to the school council.', 'Last cycle: “Optimize Facility Maintenance and MOOE Utilization”; Result: score improved by 6.8 from 72.5% to 79.3%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 79.30, 'openai/gpt-oss-120b', 0, 0, NULL, 37, '2026-10-11 14:01:19', 0),
(43, 1, '2002-2003', 25, 'Enhance curriculum alignment and monitoring', 'Strengthen curriculum relevance and instructional quality through regular collaborative planning and monitoring.\n- Curriculum Coordinator to lead monthly collaborative planning sessions with teachers to integrate local culture and peace values into lesson plans (indicator 1.4) by the 5th of each month.\n- Grade Level Leaders to conduct quarterly peer observations focusing on differentiated instruction and provide feedback reports (indicator 1.6) within two weeks after each observation.\n- ALS Coordinator to develop a bi‑monthly progress dashboard tracking ALS learner certification rates and remedial interventions (indicator 1.3) with updates submitted to the principal.', 'Last cycle: “Strengthen Curriculum Delivery and Materials”; Result: score improved by 13.8 from 67.8% to 81.6%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 81.60, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 14:14:09', 0),
(44, 1, '2002-2003', 26, 'Strengthen learning environment safety and ALS functionality', 'Promote a safe, inclusive environment and ensure the school‑based ALS program operates effectively.\n- Guidance Counselor to implement a monthly child‑protection awareness workshop for staff and students, documenting attendance (indicator 2.2) by the 10th of each month.\n- ALS Coordinator to establish a bi‑monthly review of ALS enrollment and attendance, ensuring a functional program (indicator 2.6) with a report to the principal.\n- Facilities Officer to create a monthly maintenance schedule for classroom furniture and submit a compliance checklist (indicator 2.1) by the 15th of each month.', 'Last cycle: “Promote a Safe and Inclusive School Climate”; Result: score improved by 6.3 from 66.0% to 72.3%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 72.30, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 14:14:09', 0),
(45, 1, '2002-2003', 27, 'Deepen school‑community planning and leadership capacity', 'Build stronger links between school leadership and community partners while developing emerging leaders.\n- School Head to organize quarterly leadership reflection sessions with the School‑Community Planning Team to assess strategic alignment (indicator 3.2) and produce action minutes within one week.\n- Assistant Principal to launch a mentorship program pairing experienced teachers with emerging leaders, meeting bi‑monthly and reporting progress (indicator 3.2).\n- Community Liaison Officer to produce a semi‑annual impact report on community partnership outcomes, sharing with the Division Office by the 15th of the reporting month.', 'Last cycle: “Enhance School‑Community Planning Leadership”; Result: score improved by 14.4 from 66.9% to 81.3%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 81.30, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 14:14:09', 0),
(46, 1, '2002-2003', 28, 'Improve governance monitoring and council functionality', 'Enhance transparency and accountability through systematic monitoring and a functional School Governance Council.\n- Governance Committee Chair to schedule a bi‑annual review of program performance using a standardized monitoring template (indicator 4.5) and present findings to the School Governance Council by the 20th of the review month.\n- Strategic Planning Officer to facilitate the formation of a functional School Governance Council (indicator 4.2) with clear terms of reference, meeting monthly, and submit the charter to the Division Office within 30 days.\n- School Secretary to update the public KPI dashboard quarterly, adding a governance metrics section and notifying stakeholders via email.', 'Last cycle: “Strengthen Stakeholder Satisfaction and Plan Execution”; Result: score was unchanged from 70.8% to 70.8%, and no improvement plan was created.', 'Low', 'low', 'sufficient', 70.80, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 14:14:09', 0),
(47, 1, '2002-2003', 29, 'Optimize staff compensation and professional growth', 'Ensure timely salary delivery and foster continuous professional development for all staff.\n- HR Officer to implement an automated salary processing checklist, verifying all entries by the 3rd of each month (indicator 5.6) and logging any discrepancies for resolution within 5 days.\n- Department Heads to hold monthly professional development workshops focusing on instructional strategies, with attendance recorded and follow‑up action plans submitted within one week.\n- Principal to introduce a quarterly staff appreciation program aligned with DepEd Order No. 007, s. 2024, highlighting exemplary performance during assemblies.', 'Last cycle: “Ensure Timely Compensation and Staff Support”; Result: score improved by 7.9 from 67.1% to 75.0%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 75.00, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 14:14:09', 0),
(48, 1, '2002-2003', 30, 'Advance infrastructure improvement and financial oversight', 'Strengthen resource management by enhancing financial monitoring and planning for infrastructure upgrades.\n- Finance Officer to prepare a quarterly variance analysis of MOOE expenditures against the approved budget (indicator 6.6) and present to the principal by the 10th of the following month.\n- Facilities Manager to develop a five‑year infrastructure improvement roadmap, prioritizing projects based on safety assessments, and submit the draft to the school council by 30 April (indicator 6.2).\n- Principal to authorize a bi‑annual internal audit of procurement processes, generating a compliance report and recommendations within 30 days of each audit.', 'Last cycle: “Optimize Facility Maintenance and MOOE Utilization”; Result: score improved by 6.8 from 72.5% to 79.3%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 79.30, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 14:14:09', 0),
(49, 1, '2003-2004', 25, 'Boost Curriculum Relevance via Industry Partnerships', '**Curriculum and Teaching**\nThe recent dip signals a need to enrich TLE‑TVL courses with real‑world relevance. Strengthen ties with local businesses to enhance learning outcomes.\n- Curriculum Coordinator to map local industry needs and schedule quarterly partnership meetings (indicator 1.8) by the end of each quarter.\n- Grade Level Leaders to co‑design two TLE‑TVL modules per semester incorporating industry input, with lesson plans submitted within two weeks after each design session.\n- ALS Coordinator to pilot a joint apprenticeship program for senior students, enrolling at least 10 learners per cycle and reporting progress monthly.', 'Last cycle: “Enhance curriculum alignment and monitoring”; Result: score declined by 7.5 from 81.6% to 74.1%, and no improvement plan was created.', 'Low', 'low', 'sufficient', 74.10, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 15:17:24', 0),
(50, 1, '2003-2004', 26, 'Expand Inclusive Access for Disadvantaged Learners', '**Learning Environment**\nWhile overall scores rose, access for disadvantaged, out‑of‑school and adult learners remains emerging. Target outreach and support mechanisms.\n- Guidance Counselor to conduct bi‑monthly community outreach sessions identifying eligible learners (indicator 2.5) and compile enrollment lists within five days.\n- Facilities Officer to ensure barrier‑free classroom setups for ALS participants, completing monthly checks and submitting a compliance report.\n- ALS Coordinator to launch a scholarship micro‑grant for 5 learners each term, with applications reviewed and awards announced within three weeks of the term start.', 'Last cycle: “Strengthen learning environment safety and ALS functionality”; Result: score improved by 8.2 from 72.3% to 80.5%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 80.50, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 15:17:24', 0),
(51, 1, '2003-2004', 27, 'Cultivate Emerging Leaders through Structured Mentoring', '**Leadership**\nThe strong score offers a platform to deepen leadership capacity. Formalize mentorship to sustain growth.\n- Assistant Principal to pair each emerging leader with a senior mentor, establishing bi‑monthly meeting schedules (indicator 3.2) and documenting action points within one week.\n- School Head to convene quarterly leadership reflection workshops with the School‑Community Planning Team, producing concise minutes and next‑step lists.\n- Community Liaison Officer to coordinate an annual community‑leadership forum, inviting local partners and reporting outcomes to the division by 15 May.', 'Last cycle: “Deepen school‑community planning and leadership capacity”; Result: score improved by 6.8 from 81.3% to 88.1%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 88.10, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 15:17:24', 0),
(52, 1, '2003-2004', 28, 'Strengthen Governance Council Effectiveness', '**Governance and Accountability**\nThe functional SGC remains at an emerging level. Enhance its operational rigor.\n- Governance Committee Chair to develop a standardized meeting agenda and minutes template, using it for every monthly SGC session (indicator 4.2) and circulating minutes within three days.\n- Strategic Planning Officer to conduct a semi‑annual performance audit of council decisions, presenting findings to the school board by the 20th of the audit month.\n- School Secretary to update the public KPI dashboard quarterly, adding a governance metrics widget and notifying stakeholders via email.', 'Last cycle: “Improve governance monitoring and council functionality”; Result: score improved by 8.4 from 70.8% to 79.2%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 79.20, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 15:17:24', 0),
(53, 1, '2003-2004', 29, 'Elevate Office Performance Commitment', '**Human Resource and Team Development**\nThe office performance rating is still emerging. Focus on systematic review and feedback.\n- HR Officer to implement a monthly performance commitment checklist for all staff (indicator 5.2), completing reviews by the 5th of each month.\n- Department Heads to hold quarterly staff appraisal meetings, recording scores and development plans within one week.\n- Principal to recognize top performers in a bi‑annual ceremony aligned with DepEd Order No. 007, s. 2024, and publish highlights on the school intranet.', 'Last cycle: “Optimize staff compensation and professional growth”; Result: score improved by 1.1 from 75.0% to 76.1%, and no improvement plan was created.', 'Low', 'high', 'sufficient', 76.10, 'openai/gpt-oss-120b', 1, 0, NULL, 37, '2026-10-11 15:17:24', 0),
