(22, 166, 3, 'coordinator_approved', 'submitted', 'approved', 46, NULL, '{\"plan_id\":166,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":25,\"indicator_id\":169,\"priority_level\":\"Medium\",\"objective\":\"By March 2003, the school will ensure that 100 % of its school‑based ALS learners attain elementary and junior high school certification, through quarterly assessment checkpoints and timely reporting overseen by the ALS Coordinator.\",\"strategy\":\"The ALS Coordinator will set quarterly assessment checkpoints that use the contextualized learning materials prepared by the Curriculum Coordinators and embed peace and DepEd core values into each checkpoint’s lesson plans, with teachers reviewing relevance monthly; after each quarter the coordinator will compile and submit a certification progress report to confirm that ALS learners are on track to attain elementary and junior high school completion.\",\"person_responsible\":\"Ms. Jedie\",\"target_date\":\"2003-03-20\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"approved\",\"current_owner_role\":\"sbm_coordinator\",\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:03:37\",\"remarks\":null,\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":46,\"approved_at\":\"2026-10-11 13:03:37\",\"validated_by\":null,\"validated_at\":null,\"created_at\":\"2026-10-11 12:31:04\",\"updated_at\":\"2026-10-11 13:03:37\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:03:37'),
(23, 168, 3, 'coordinator_returned', 'submitted', 'returned_to_school_head', 46, 'conduct a seminar for teachers on how to eliminate the deficiencies', '{\"plan_id\":168,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":26,\"indicator_id\":184,\"priority_level\":\"Medium\",\"objective\":\"By December 31, 2003, the school will upgrade all classrooms, restrooms, and common areas to fully meet special‑education and PWD‑friendly standards, and will monitor compliance through monthly zero‑bullying checks and termly culture‑sensitive activities to ensure an inclusive learning environment.\",\"strategy\":\"The Facilities Officer will lead the upgrade of special‑education and PWD‑friendly facilities, ensuring all modifications are completed by 31 December, while Guidance Counselors launch a zero‑bullying awareness program with monthly monitoring and the Student Welfare Committee conducts culture‑sensitive activities each term to foster an inclusive, safe learning environment.\",\"person_responsible\":\"Mr. Head Officer\",\"target_date\":\"2003-12-30\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"returned_to_school_head\",\"current_owner_role\":\"school_head\",\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:05:06\",\"remarks\":\"conduct a seminar for teachers on how to eliminate the deficiencies\",\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":null,\"approved_at\":null,\"validated_by\":null,\"validated_at\":null,\"created_at\":\"2026-10-11 12:33:34\",\"updated_at\":\"2026-10-11 13:05:06\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:05:06'),
(24, 167, 3, 'coordinator_approved', 'submitted', 'approved', 46, NULL, '{\"plan_id\":167,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":26,\"indicator_id\":175,\"priority_level\":\"Medium\",\"objective\":\"By the end of the academic year, the school will achieve zero bullying incidents, as verified by monthly monitoring reports from the Guidance Counselor’s zero‑bullying awareness program.\",\"strategy\":\"The Guidance Counselors will launch a zero‑bullying awareness program with monthly monitoring of incidents and prompt follow‑up actions, and the Student Welfare Committee will reinforce a respectful climate by organizing culture‑sensitive activities each term; both teams will hold regular coordination meetings to review data, adjust interventions, and ensure the school achieves zero bullying incidence.\",\"person_responsible\":\"Mr. Principal\",\"target_date\":\"2002-04-20\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"approved\",\"current_owner_role\":\"sbm_coordinator\",\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:05:18\",\"remarks\":null,\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":46,\"approved_at\":\"2026-10-11 13:05:18\",\"validated_by\":null,\"validated_at\":null,\"created_at\":\"2026-10-11 12:32:09\",\"updated_at\":\"2026-10-11 13:05:18\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:05:18'),
(25, 169, 3, 'coordinator_approved', 'submitted', 'approved', 46, NULL, '{\"plan_id\":169,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":26,\"indicator_id\":178,\"priority_level\":\"Medium\",\"objective\":\"The school will achieve a 90% student and staff satisfaction rating by year‑end through monthly zero‑bullying awareness sessions, completion of all special‑education and PWD‑friendly facility upgrades by 31 December, and the delivery of at least one culture‑sensitive activity each term.\",\"strategy\":\"The Student Welfare Committee will lead the planning and execution of culture‑sensitive activities each term, collaborating with the Guidance Counselor’s zero‑bullying program and the Facilities Officer to secure inclusive, PWD‑friendly venues, and will submit monthly participation reports to monitor progress toward indicator 2.4; all activities will be scheduled in coordination with the school calendar and evaluated against the termly monitoring data to ensure cultural relevance and safety.\",\"person_responsible\":\"Head Teacher\",\"target_date\":\"2002-04-20\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"approved\",\"current_owner_role\":\"sbm_coordinator\",\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:05:20\",\"remarks\":null,\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":46,\"approved_at\":\"2026-10-11 13:05:20\",\"validated_by\":null,\"validated_at\":null,\"created_at\":\"2026-10-11 12:38:07\",\"updated_at\":\"2026-10-11 13:05:20\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:05:20'),
(26, 170, 3, 'coordinator_approved', 'submitted', 'approved', 46, NULL, '{\"plan_id\":170,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":27,\"indicator_id\":186,\"priority_level\":\"Medium\",\"objective\":\"By the end of the academic year, the school will maintain a functional school‑community planning team that meets monthly, develops and implements at least three community‑focused action plans, and submits bi‑monthly progress reports to the School Head. This will ensure consistent strategic planning and execution as required by indicator 3.2.\",\"strategy\":\"The School Head will convene the school‑community planning team monthly to set and prioritize action items, while the Vice Principal mentors department heads on strategic‑plan execution and provides bi‑monthly progress reports to the team; teachers will submit quarterly leadership reflections that are reviewed to inform decision‑making and sustain a functional planning process.\",\"person_responsible\":\"Vice Principal\",\"target_date\":\"2002-05-30\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"approved\",\"current_owner_role\":\"sbm_coordinator\",\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:05:23\",\"remarks\":null,\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":46,\"approved_at\":\"2026-10-11 13:05:23\",\"validated_by\":null,\"validated_at\":null,\"created_at\":\"2026-10-11 12:39:09\",\"updated_at\":\"2026-10-11 13:05:23\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:05:23'),
(27, 171, 3, 'coordinator_approved', 'submitted', 'approved', 46, NULL, '{\"plan_id\":171,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":29,\"indicator_id\":200,\"priority_level\":\"Medium\",\"objective\":\"The school will guarantee that all salaries, allowances, and additional compensation are processed accurately and disbursed within five business days of submission, with monthly audits to monitor compliance.\",\"strategy\":\"The HR Officer will verify and process all salary, allowance, and additional compensation submissions within five business days, supported by a monthly audit to ensure accuracy and timeliness, while the Professional Development Coordinator will deliver quarterly training on DepEd Order No. 007, s. 2024 to keep staff informed of compensation policies, and the School Head will conduct semi‑annual performance reviews and share feedback to reinforce compliance and promptly address any discrepancies.\",\"person_responsible\":\"HR Office\",\"target_date\":\"2002-09-20\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"approved\",\"current_owner_role\":\"sbm_coordinator\",\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:05:32\",\"remarks\":null,\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":46,\"approved_at\":\"2026-10-11 13:05:32\",\"validated_by\":null,\"validated_at\":null,\"created_at\":\"2026-10-11 12:40:55\",\"updated_at\":\"2026-10-11 13:05:32\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:05:32'),
(28, 164, 4, 'coordinator_validated', 'approved', 'finalized', 46, NULL, '{\"plan_id\":164,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":25,\"indicator_id\":172,\"priority_level\":\"Medium\",\"objective\":\"By the end of the school year, teachers will integrate peace and DepEd core values into 100 % of weekly lesson plans across all grade levels, with monthly reviews confirming consistent implementation.\",\"strategy\":\"The lead teachers will embed peace and DepEd core values into each weekly lesson plan, aligning activities with the curriculum framework, and the curriculum team will conduct monthly reviews of these plans to ensure fidelity and provide feedback; necessary contextualized materials will be prepared by the curriculum coordinators by 30 June to support teachers in delivering value‑based content across all grade levels.\",\"person_responsible\":\"Ms. France De Guzman\",\"target_date\":\"2002-06-30\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"finalized\",\"current_owner_role\":null,\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:05:36\",\"remarks\":null,\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":46,\"approved_at\":\"2026-10-11 13:03:32\",\"validated_by\":46,\"validated_at\":\"2026-10-11 13:05:36\",\"created_at\":\"2026-10-11 12:29:19\",\"updated_at\":\"2026-10-11 13:05:36\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:05:36'),
(29, 165, 4, 'coordinator_validated', 'approved', 'finalized', 46, NULL, '{\"plan_id\":165,\"school_id\":1,\"cycle_id\":6,\"dimension_id\":25,\"indicator_id\":170,\"priority_level\":\"Medium\",\"objective\":\"By 30 June 2002, curriculum coordinators and teachers will develop and implement contextualized learning materials for all grade levels that respond to learners’ needs and embed peace and DepEd core values. This will achieve at least a 15 % increase in student engagement scores as measured by quarterly surveys.\",\"strategy\":\"The Curriculum Coordinators will design and produce grade‑level contextualized learning materials that reflect learners’ local realities and DepEd core values, completing the drafts by 30 June; teachers will adapt these resources into weekly lesson plans, integrating peace and core values, and submit them for monthly review to ensure relevance and responsiveness to student needs.\",\"person_responsible\":\"Ms. Jedie\",\"target_date\":\"2002-06-30\",\"resources_needed\":null,\"expected_output\":null,\"status\":\"planned\",\"workflow_status\":\"finalized\",\"current_owner_role\":null,\"current_owner_user_id\":null,\"last_action_by\":46,\"last_action_at\":\"2026-10-11 13:05:38\",\"remarks\":null,\"created_by\":37,\"submitted_by\":37,\"submitted_at\":\"2026-10-11 12:42:39\",\"approved_by\":46,\"approved_at\":\"2026-10-11 13:03:34\",\"validated_by\":46,\"validated_at\":\"2026-10-11 13:05:38\",\"created_at\":\"2026-10-11 12:30:17\",\"updated_at\":\"2026-10-11 13:05:38\",\"suggestion_item_id\":null,\"suggestion_baseline_text\":null,\"is_sample\":0}', '2026-10-11 05:05:38'),
